using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using McpServer;

var builder = Host.CreateApplicationBuilder(args);

builder.Services
    .AddHttpClient("WeatherApi", client =>
    {
        client.BaseAddress = new Uri("https://api.weatherapi.com/v1/");
    });

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();

using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly IHttpClientFactory _httpClientFactory;

    // Constructor injection — the MCP SDK resolves dependencies from the DI container
    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [McpServerTool, Description("Get current weather for a location")]
    public async Task<string> GetCurrentWeather(
        [Description("City name or coordinates (e.g. 'London' or '48.8,2.3')")] string location,
        CancellationToken cancellationToken = default)
    {
        var client = _httpClientFactory.CreateClient("WeatherApi");

        var response = await client.GetAsync(
            $"current.json?key=YOUR_API_KEY&q={Uri.EscapeDataString(location)}",
            cancellationToken);

        if (!response.IsSuccessStatusCode)
        {
            return $"Error: Weather API returned {response.StatusCode}";
        }

        var weather = await response.Content.ReadFromJsonAsync<WeatherResponse>(cancellationToken);

        return $"""
            Location: {weather?.Location?.Name}, {weather?.Location?.Country}
            Temperature: {weather?.Current?.TempC}°C / {weather?.Current?.TempF}°F
            Condition: {weather?.Current?.Condition?.Text}
            Humidity: {weather?.Current?.Humidity}%
            Wind: {weather?.Current?.WindKph} km/h
            """;
    }

    [McpServerTool, Description("Get weather forecast for a location")]
    public async Task<string> GetForecast(
        [Description("City name or coordinates")] string location,
        [Description("Number of forecast days (1-3)")] int days = 3,
        CancellationToken cancellationToken = default)
    {
        var client = _httpClientFactory.CreateClient("WeatherApi");

        var response = await client.GetAsync(
            $"forecast.json?key=YOUR_API_KEY&q={Uri.EscapeDataString(location)}&days={days}",
            cancellationToken);

        if (!response.IsSuccessStatusCode)
        {
            return $"Error: Weather API returned {response.StatusCode}";
        }

        var content = await response.Content.ReadAsStringAsync(cancellationToken);
        return content;
    }
}

// Response models
public sealed class WeatherResponse
{
    [JsonPropertyName("location")]
    public LocationInfo? Location { get; set; }

    [JsonPropertyName("current")]
    public CurrentWeather? Current { get; set; }
}

public sealed class LocationInfo
{
    [JsonPropertyName("name")]
    public string? Name { get; set; }

    [JsonPropertyName("country")]
    public string? Country { get; set; }
}

public sealed class CurrentWeather
{
    [JsonPropertyName("temp_c")]
    public double TempC { get; set; }

    [JsonPropertyName("temp_f")]
    public double TempF { get; set; }

    [JsonPropertyName("condition")]
    public WeatherCondition? Condition { get; set; }

    [JsonPropertyName("humidity")]
    public int Humidity { get; set; }

    [JsonPropertyName("wind_kph")]
    public double WindKph { get; set; }
}

public sealed class WeatherCondition
{
    [JsonPropertyName("text")]
    public string? Text { get; set; }
}

